/**
 * 演出エフェクト品質スコア（採点ハーネスの成果物）。
 * lib/xp-clean-status.ts と同型。図鑑（UnifiedGallery）がグレードチップ表示・
 * ワーストソート・「private&Cから直す」プリセットに使う。
 *
 * FX_SCORE の本体は scripts/fx-score-merge.mjs が採点JSON群から機械生成する
 * （下の GENERATED マーカー間を置換）。手で編集しない。
 *
 * キー: native=effect id / 拡張=素の port id（xp- prefixなし）。
 * 採点軸は「桜レベル」基準の4軸: シルエット/奥行き/動きの質/光・質感（各0-2点）。
 */

export type FxGrade = "A" | "B" | "C";

export interface FxScore {
  grade: FxGrade;
  axes: {
    silhouette: number; // ①形状（矩形/円=0, 対象固有シルエット=2）
    depth: number; // ②奥行き（平面=0, DOF/ボケ=2）
    motion: number; // ③動きの質（静止/線形=0, フラッター/非線形=2）
    light: number; // ④光・質感（フラット=0, 加算/グロー=2）
  };
  verdict: string; // 一言講評
  fix: string; // 桜化の具体1手
}

