/** native id / 拡張素id / "xp-"prefix付き のどれでも引く（未採点=undefined） */
export function fxScoreOf(id: string): FxScore | undefined {
  return FX_SCORE[id] ?? FX_SCORE[id.startsWith("xp-") ? id.slice(3) : id];
}

